<script>document.addEventListener('click',function(e){var menu=document.querySelector('.profile-menu');if(menu&&!menu.contains(e.target)){var d=document.getElementById('profileDropdown');var t=document.querySelector('.profile-trigger');if(d){d.classList.remove('open');}if(t){t.classList.remove('open');}}});</script>
